import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as i,af as s}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"MiniMax Code cookbook","description":"Official recipes only: Agent Team, your own API key, headless exec, ACP, check-in credits.","frontmatter":{"title":"MiniMax Code cookbook","description":"Official recipes only: Agent Team, your own API key, headless exec, ACP, check-in credits.","domain":"product","tags":["coding-agent"],"role":"cookbook"},"headers":[],"relativePath":"products/minimax-code/minimax-code-cookbook.md","filePath":"products/minimax-code/minimax-code-cookbook.md","lastUpdated":1787107158000}'),o={name:"products/minimax-code/minimax-code-cookbook.md"};function n(d,e,r,l,c,p){return i(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="minimax-code-cookbook" tabindex="-1">MiniMax Code cookbook <a class="header-anchor" href="#minimax-code-cookbook" aria-label="Permalink to &quot;MiniMax Code cookbook&quot;">​</a></h1><p>Skip around. Install and the first conversation live in the <a href="./minimax-code.html">tutorial</a>. This page is &quot;I need to do X&quot;.</p><h2 id="_1-use-agent-team-on-a-complex-task" tabindex="-1">1. Use Agent Team on a complex task <a class="header-anchor" href="#_1-use-agent-team-on-a-complex-task" aria-label="Permalink to &quot;1. Use Agent Team on a complex task&quot;">​</a></h2><p>Source: <a href="https://agent.minimax.io/docs/code/agents/team" target="_blank" rel="noreferrer">Agent Team</a>.</p><p>Official text: Agent Team &quot;introduces multiple specialist Agents based on task complexity. You still only describe the goal&quot;; MiniMax Code handles decomposition, assignment, progress, and the summary.</p><p>Use it when the work:</p><ul><li>Mixes code, design, docs, and tests</li><li>Must run for a long time</li><li>Needs split execution plus verification</li><li>Needs parallel exploration</li></ul><p>Write a clear goal, acceptance bar, and constraints. You can add instructions mid-flight; the official page says Agent Team folds them into later steps.</p><p>The M3 post describes a Producer + Verifier loop and multi-day unattended runs (<a href="https://www.minimax.io/blog/minimax-m3" target="_blank" rel="noreferrer">minimax-m3</a>). Treat that as product language, not an SLA. Queue limits stay on the <a href="https://agent.minimax.io/docs/code/agents/team" target="_blank" rel="noreferrer">team</a> page and in the app.</p><p>Skip Team for a one-file edit.</p><h2 id="_2-use-your-own-minimax-api-key" tabindex="-1">2. Use your own MiniMax API key <a class="header-anchor" href="#_2-use-your-own-minimax-api-key" aria-label="Permalink to &quot;2. Use your own MiniMax API key&quot;">​</a></h2><p>Source: <a href="https://agent.minimax.io/docs/code/account/minimax-api" target="_blank" rel="noreferrer">MiniMax API Key</a>.</p><ol><li>Open usage / model settings.</li><li>Choose MiniMax API, paste the key, save.</li><li>Run the connection test.</li></ol><p>Official warning: do not put the key in chat, a repo, or a public doc. Use the in-product field only.</p><p>On the CLI, run <code>mcode provider</code> or <code>mcode provider --help</code> (<a href="https://agent.minimax.io/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>).</p><p>Custom providers (base URL, API format, model name) use <a href="https://agent.minimax.io/docs/code/account/byok" target="_blank" rel="noreferrer">BYOK</a>. Do not merge that flow with the official MiniMax key.</p><h2 id="_3-run-one-headless-cli-task" tabindex="-1">3. Run one headless CLI task <a class="header-anchor" href="#_3-run-one-headless-cli-task" aria-label="Permalink to &quot;3. Run one headless CLI task&quot;">​</a></h2><p>Source: <a href="https://agent.minimax.io/docs/cli/features" target="_blank" rel="noreferrer">Features</a>.</p><p><code>mcode exec</code> does not start the TUI.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Fix the failing tests&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mcode</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --cwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./repo</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --file</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> error.log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  --output-format</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &quot;Analyze the error log, fix the issue, and run the related tests&quot;</span></span></code></pre></div><p>Official flags:</p><table tabindex="0"><thead><tr><th>Flag</th><th>Purpose</th></tr></thead><tbody><tr><td><code>--cwd</code></td><td>Workspace directory</td></tr><tr><td><code>--file</code></td><td>Attachment; repeatable</td></tr><tr><td><code>--model</code></td><td>Model for this run only</td></tr><tr><td><code>--session</code> / <code>--continue</code></td><td>Existing session</td></tr><tr><td><code>--permission</code></td><td><code>ask</code>, <code>smart</code>, <code>full</code>, or <code>off</code></td></tr><tr><td><code>--timeout</code></td><td>e.g. <code>30s</code>, <code>2m</code></td></tr><tr><td><code>--max-steps</code></td><td>Cap assistant steps</td></tr><tr><td><code>--output-format</code></td><td><code>text</code>, <code>json</code>, or <code>stream-json</code></td></tr><tr><td><code>--output-schema</code></td><td>JSON Schema for the final JSON</td></tr></tbody></table><p>Task output goes to <code>stdout</code>. Diagnostics go to <code>stderr</code>. stdin is read only with explicit <code>--input -</code>, so CI does not hang.</p><h2 id="_4-attach-mcode-to-zed-acp" tabindex="-1">4. Attach <code>mcode</code> to Zed (ACP) <a class="header-anchor" href="#_4-attach-mcode-to-zed-acp" aria-label="Permalink to &quot;4. Attach \`mcode\` to Zed (ACP)&quot;">​</a></h2><p>Source: <a href="https://agent.minimax.io/docs/cli/features" target="_blank" rel="noreferrer">Features</a>.</p><p><code>mcode acp</code> runs as an ACP v1 agent server over stdin/stdout NDJSON. Official text: no extra HTTP server, and the editor does not need a MiniMax-only plugin.</p><p>Zed External Agents example (official):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;agent_servers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;minimax-code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;custom&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mcode&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;acp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>If the editor cannot find the binary, set <code>command</code> to the absolute path of <code>mcode</code>. Official constraint: <code>stdout</code> is protocol-only. Do not type natural language into that stream. Do not let a wrapper log to <code>stdout</code>.</p><p>Do not invent an official VS Code plugin.</p><h2 id="_5-usage-and-check-in-credits" tabindex="-1">5. Usage and check-in credits <a class="header-anchor" href="#_5-usage-and-check-in-credits" aria-label="Permalink to &quot;5. Usage and check-in credits&quot;">​</a></h2><p>Source: <a href="https://agent.minimax.io/docs/code/account/usage" target="_blank" rel="noreferrer">Token Plan and Credits</a>.</p><p>The usage page shows plan status, Token Plan validity, credit balance, quotas, and the subscribe / top-up / invoice / check-in entries.</p><p>Official check-in numbers on that page:</p><ul><li>Daily check-in: <strong>400</strong> credits</li><li>Day 4 and day 7 streaks: <strong>1000</strong> credits that day</li><li>Full week: <strong>4000</strong> credits total</li><li>Credits expire <strong>30 days</strong> after they land</li></ul><p>Same page: &quot;Follow the in-product display for specific billing and quota rules.&quot; (CN twin: 「具体计费和额度规则以产品内展示为准。」)</p><p>Desktop Plus / Max / Ultra list prices and Open Platform Token Plan USD tiers are <strong>not</strong> one table. See the <a href="./minimax-code-cheatsheet.html">cheatsheet</a>.</p><h2 id="_6-a-scheduled-task-did-not-run" tabindex="-1">6. A scheduled task did not run <a class="header-anchor" href="#_6-a-scheduled-task-did-not-run" aria-label="Permalink to &quot;6. A scheduled task did not run&quot;">​</a></h2><p>Source: <a href="https://agent.minimax.io/docs/code/help/faq" target="_blank" rel="noreferrer">desktop FAQ</a>.</p><p>Confirm the machine is awake, MiniMax Code is running, and the task is enabled.</p><p>The CLI does not host the desktop scheduler. Official FAQ: Browser and Computer Use appear only when the current host actually provides them. Do not assume the CLI has every desktop capability.</p><h2 id="_7-install-failures" tabindex="-1">7. Install failures <a class="header-anchor" href="#_7-install-failures" aria-label="Permalink to &quot;7. Install failures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Official fix</th></tr></thead><tbody><tr><td><code>mcode: command not found</code></td><td>Reopen the terminal; check <code>PATH</code>; fully quit VS Code (<a href="https://agent.minimax.io/docs/cli/faq" target="_blank" rel="noreferrer">CLI FAQ</a>)</td></tr><tr><td>Installer fails</td><td>Reach the MiniMax file CDN, Node.js.org, and the npm registry; native deps may also hit GitHub. Set <code>HTTP_PROXY</code> / <code>HTTPS_PROXY</code> / <code>ALL_PROXY</code> / <code>NO_PROXY</code> first</td></tr><tr><td>Alpine / musl</td><td>Not supported</td></tr><tr><td>Windows desktop will not install</td><td>OS version, install-path permissions, corporate proxy (<a href="https://agent.minimax.io/docs/code/get-started/download" target="_blank" rel="noreferrer">download</a>)</td></tr><tr><td>Custom model will not connect</td><td>Base URL, API key, model name, network, API format (<a href="https://agent.minimax.io/docs/code/help/faq" target="_blank" rel="noreferrer">desktop FAQ</a>)</td></tr></tbody></table><p>Steps for pointing MiniMax-M3 at Claude Code / Cursor live on <a href="https://platform.minimax.io/docs/guides/text-ai-coding-tools" target="_blank" rel="noreferrer">text-ai-coding-tools</a>. They are not MiniMax Code recipes.</p>`,44)])])}const f=t(o,[["render",n]]);export{g as __pageData,f as default};
